class UI{constructor(t){this.tg=t}showLoading(t="Загрузка..."){const e=this.tg.MainButton;e.setText(t),e.showProgress(),e.disable()}hideLoading(t="Сохранить"){const e=this.tg.MainButton;e.hideProgress(),e.setText(t),e.enable()}showSuccess(t,e){this.tg.showAlert(t,e),this.tg.HapticFeedback.notificationOccurred("success")}showError(t){this.tg.showAlert(t),this.tg.HapticFeedback.notificationOccurred("error")}showWarning(t){this.tg.showAlert(t),this.tg.HapticFeedback.notificationOccurred("warning")}confirmAction(t,e){this.tg.showConfirm(t,(t=>{t&&e()}))}showPopup(t){this.tg.showPopup(t)}hapticLight(){this.tg.HapticFeedback.impactOccurred("light")}hapticMedium(){this.tg.HapticFeedback.impactOccurred("medium")}hapticHeavy(){this.tg.HapticFeedback.impactOccurred("heavy")}hapticSelection(){this.tg.HapticFeedback.selectionChanged()}formatAmount(t){return new Intl.NumberFormat("ru-RU",{style:"decimal",minimumFractionDigits:2,maximumFractionDigits:2}).format(Math.abs(t))}formatDate(t){const e="string"==typeof t?new Date(t):t;return new Intl.DateTimeFormat("ru-RU",{day:"numeric",month:"long",year:"numeric"}).format(e)}formatDateShort(t){const e="string"==typeof t?new Date(t):t;return new Intl.DateTimeFormat("ru-RU",{day:"numeric",month:"short"}).format(e)}formatTime(t){const e="string"==typeof t?new Date(t):t;return new Intl.DateTimeFormat("ru-RU",{hour:"2-digit",minute:"2-digit"}).format(e)}show(t){const e="string"==typeof t?document.querySelector(t):t;e&&(e.style.display="")}hide(t){const e="string"==typeof t?document.querySelector(t):t;e&&(e.style.display="none")}toggle(t){const e="string"==typeof t?document.querySelector(t):t;e&&(e.style.display="none"===e.style.display?"":"none")}}